-- Adaptive pickleball across the US (docs/data-fixes/adaptive-pickleball.md). Researched 2026-10-26 from each organization's own page.
-- Safe to run twice: fixed ids with INSERT OR IGNORE, and each insert is skipped when the row already exists.
-- New organizations, each confirmed current from its own page. Works with or without migration 0015.

-- Exeter Parks and Recreation Adaptive Pickleball (Exeter, NH). Source: https://www.exeternh.gov/recreation/2026-adaptive-pickleball
INSERT OR IGNORE INTO organizations (id, name, org_type, sport, sport_key, sports_json, website_url, city, state, state_name, country, description, verification_status, status, is_public, primary_data_source, created_at, updated_at)
  SELECT 'c855a11e-222e-5ba4-9e97-cbf7003a42de', 'Exeter Parks and Recreation Adaptive Pickleball', 'Parks and recreation', 'Pickleball', 'pickleball', '["pickleball"]', 'https://www.exeternh.gov/recreation/2026-adaptive-pickleball', 'Exeter', 'NH', 'New Hampshire', 'United States',
    'Exeter Parks and Recreation offers free adaptive pickleball on Tuesday evenings in summer, with volunteers teaching at any pace and sport wheelchairs, a ball launcher and adaptive paddle grips supplied through Northeast Passage. All are welcome, and the program is open to Exeter and surrounding towns.', 'unverified', 'active', 1, 'ASNM research 2026-10-26', strftime('%Y-%m-%dT%H:%M:%SZ','now'), strftime('%Y-%m-%dT%H:%M:%SZ','now')
  WHERE NOT EXISTS (SELECT 1 FROM organizations WHERE website_url = 'https://www.exeternh.gov/recreation/2026-adaptive-pickleball' OR (name = 'Exeter Parks and Recreation Adaptive Pickleball' COLLATE NOCASE AND state = 'NH'));

