-- Parks Tacoma Adaptive Pickleball (Tacoma, WA). Source: https://www.parkstacoma.gov/activities-and-sports/category/as/adaptive/
INSERT OR IGNORE INTO organizations (id, name, org_type, sport, sport_key, sports_json, website_url, city, state, state_name, country, description, verification_status, status, is_public, primary_data_source, created_at, updated_at)
  SELECT '2d3f6ed4-a266-592c-9826-7cdad0800848', 'Parks Tacoma Adaptive Pickleball', 'Parks_and_recreation', 'Pickleball', 'pickleball', '["pickleball"]', 'https://www.parkstacoma.gov/activities-and-sports/category/as/adaptive/', 'Tacoma', 'WA', 'Washington', 'United States',
    'Parks Tacoma has a designated adaptive pickleball court during Saturday evening open play at Schatz Gym and hosts a quarterly series of adaptive pickleball clinics. The clinics teach wheelchair maneuvering, positioning and pickleball basics for people with physical disabilities in an inclusive setting.', 'unverified', 'active', 1, 'ASNM research 2026-10-26', strftime('%Y-%m-%dT%H:%M:%SZ','now'), strftime('%Y-%m-%dT%H:%M:%SZ','now')
